shell_commands:
python3 - <<'EOF'
p='src/orchestration/tools/registry.ts'
s=open(p).read()
fp='''function fieldPath(error: SchemaError): string {
  const raw = error.instancePath ?? error.dataPath ?? '';
  return raw.replace(/^[./]/, '').replace(/\\//g, '.');
}

'''
assert fp in s
s=s.replace(fp,'')
anchor="  return `'${fieldPath(error)}' ${error.message ?? 'is invalid'}`;\n}\n\n"
assert anchor in s
s=s.replace(anchor, anchor+fp)
open(p,'w').write(s)
EOF
cat >> src/orchestration/tools/registry.test.ts <<'EOF'

describe('ToolRegistry.execute enum validation', () => {
  it('names an off-enum field and its allowed values without echoing its value', async () => {
    const {registry, inputs} = recordingRegistry({
      name: 'convert',
      description: 'c',
      inputSchema: {type: 'object', properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}}},
    });

    const response = await registry.execute('convert', {unit: 'jane.doe@example.com'});

    expect({inputs, result: response.result}).toEqual({
      inputs: [],
      result: "Invalid input for tool convert: 'unit' must be one of: celsius, fahrenheit",
    });
  });
});
EOF
timeout 300 npx jest src/orchestration/tools/registry.test.ts 2>&1 | tail -25
